ALTER POLICY "payment_facts_select_buyer_own" ON "payment_facts" TO authenticated USING (("payment_facts"."direction" = 'inbound' or ("payment_facts"."direction" = 'outbound' and "payment_facts"."kind" = 'refund')) and "payment_facts"."order_id" in (select o.id from "orders" o join "requests" r on r.id = o.request_id where r.buyer_company_id = (select public.current_company_id())));